import { useRef, useCallback } from "react";

export const useTableKeyboardNav = () => {
  const tableRef = useRef<HTMLTableElement>(null);

  const getCell = (row: number, col: number) => {
    return tableRef.current?.querySelector<HTMLElement>(`[data-row="${row}"][data-col="${col}"]`);
  };

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLElement>) => {
    const { key, currentTarget } = e;
    const { row: currentRow, col: currentCol } = (currentTarget as HTMLElement).dataset;

    if (currentRow === undefined || currentCol === undefined) return;

    let nextRow = parseInt(currentRow, 10);
    let nextCol = parseInt(currentCol, 10);

    const isCtrlOrMeta = e.ctrlKey || e.metaKey;

    switch (key) {
      case "ArrowUp":
        nextRow = Math.max(0, nextRow - 1);
        break;
      case "ArrowDown": {
        const maxRow = (tableRef.current?.rows.length ?? 0) - 1;
        nextRow = Math.min(maxRow, nextRow + 1);
        break;
      }
      case "ArrowLeft":
        nextCol = Math.max(0, nextCol - 1);
        break;
      case "ArrowRight": {
        const maxCol = (tableRef.current?.rows[nextRow]?.cells.length ?? 0) - 1;
        nextCol = Math.min(maxCol, nextCol + 1);
        break;
      }
      case "Home":
        if (isCtrlOrMeta) {
          nextRow = 0;
          nextCol = 0;
        } else {
          nextCol = 0;
        }
        break;
      case "End": {
        if (isCtrlOrMeta) {
          const maxRow = (tableRef.current?.rows.length ?? 0) - 1;
          const maxCol = (tableRef.current?.rows[maxRow]?.cells.length ?? 0) - 1;
          nextRow = maxRow;
          nextCol = maxCol;
        } else {
          const maxCol = (tableRef.current?.rows[nextRow]?.cells.length ?? 0) - 1;
          nextCol = maxCol;
        }
        break;
      }
      case "PageUp":
        nextRow = 0;
        break;
      case "PageDown": {
        const maxRow = (tableRef.current?.rows.length ?? 0) - 1;
        nextRow = maxRow;
        break;
      }
      case "Enter":
      case " ":
        e.preventDefault();
        return;
      default:
        return;
    }

    const nextCell = getCell(nextRow, nextCol);
    if (nextCell) {
      e.preventDefault();
      nextCell.focus();
    }
  }, []);

  return { tableRef, handleKeyDown };
};
